-- Map names
UPDATE `location_text` SET `name` = 'Forest and Hills' WHERE `id` = '10' AND `language` = 'en';
UPDATE `location_text` SET `name` = 'Snowy Mountains Peak' WHERE `id` = '19' AND `language` = 'en';

-- Location Item (Gathering)
DROP TABLE `location_item`;

CREATE TABLE `location_item` (`location_id` INTEGER NOT NULL, `rank` TEXT NOT NULL, `area` INTEGER NOT NULL, `node` INTEGER NOT NULL, `type` TEXT NOT NULL, `min` INTEGER NOT NULL, `max` INTEGER NOT NULL, `item_id` INTEGER NOT NULL, `percentage` INTEGER NOT NULL, PRIMARY KEY(`location_id`, `rank`, `area`, `node`, `item_id`), FOREIGN KEY(`item_id`) REFERENCES `item`(`id`) ON UPDATE NO ACTION ON DELETE NO ACTION );

